// NodeTypeString is Go's NodeType.String().
export function NodeTypeString(i: NodeType): string {
  const r = _NodeType_map.get(i);
  if (r !== undefined) {
    return _NodeType_name.slice(r[0], r[1]);
  }
  return "NodeType(" + strconv.FormatInt(i, 10) + ")";
}
